# geometric_k_medians

\subsection{Formal definitions and proofs}
Following [CITE:projection], we define the nearest neighbour projection:
\begin{definition}[Nearest neighbour projection]
    Let $S \subseteq \mathbb{R}^d$ be a closed set. A nearest neighbour projection on $S$ is denoted by $\pi_S$ and defined as
    \begin{gather*}
        \pi_S(x) = \sum_{s \in S} s  1_{\substack{B_s(S)}}(x), \quad x\in \mathbb{R}^d,
    \end{gather*} 
    where $1_{\substack{B_s(S)}}$ is the indicator function of $B_s(S)$ and $B(S) :=(B_s(S))_{s\in S}$ is a Borel Voronoi partition of $\mathbb{R}^d$ such that 
    $B_s(S) \subseteq \{ x \in \mathbb{R}^d : \norm{x-s} = \min_{\substack{\tilde{s} \in S}} \norm{x - \tilde{s}} \}$. 
\end{definition}
Interested readers are referred to [CITE:projection] for technical details.

\begin{remark}
    If $S$ is a finite set, then $\pi_S$  maps $x$ to a point in $S$ with minimal distance from $x$. If $S$ is not convex this point may be dependent on the choice of the Voronoi partition $B(S)$.
\end{remark}

\begin{definition} [Projection measure]
    Let $S \subseteq \mathbb{R}^d$ be a closed set and let $\pi_S$ be a nearest neighbour projection on $S$. Moreover, let $\rho$ be a probability distribution on $\mathbb{R}^d$. Then $\pi_S \rho$ denotes the distribution obtained as a push-forward of $\rho$ by $\pi_S$, i.e.\ $\pi_S \rho (A) = \rho(\pi_S^{-1}(A))$ for any $A\subset \mathbb{R}^d$.
\end{definition}

\begin{lemma} [[CITE:canas]]

     Fix $ 1 \leq p < \infty$. Let $S \subseteq \mathbb{R}^d$ be a closed set,  and let $\rho$ be a probability distribution on $\mathbb{R}^d$ with finite p-th moment. We have
    \begin{gather*}
        \mathbb{E}_{x\sim \rho} d(x, S)^p = W_p(\rho, \pi_S \rho)^p,   
    \end{gather*}
    where $d(x,S)$ denotes the distance the smallest distance from $x$ to $S$ and $W_p$ is the Wasserstein-p metric.
\end{lemma}

\begin{lemma} [[CITE:canas]]

    Fix $ 1 \leq p < \infty$. Let $S \subseteq \mathbb{R}^d$ be a closed set,  and let $\rho$ be a probability distribution on $\mathbb{R}^d$ with finite p-th moment. For all probability distributions $\mu$ with finite p-th moment such that $\text{supp}(\mu) \subseteq S$, we have
    \begin{gather*}
        W_p(\rho, \mu) \geq W_p(\rho, \pi_S \rho).
    \end{gather*}
\end{lemma}

\begin{definition} [Geometric $k$ medians]
    Let $\mathcal X=\{x_i,~i=1,\ldots,n\}$ be a data set in $\mathbb{R}^d$. Given an arbitrary set $S=\{m_i, i=1,\ldots,k\}  \subseteq \mathbb{R}^d$, let  $S_i = \{ x \in \mathcal X : m_i = \argmin_{m \in S} \norm{m - x}_2 \}$, i.e.\ $S_i$ consists of the points in $\mathcal{X}$ for which the closest point in $S$ is $m_i$.  The geometric k-medians is defined as the set $\hat{S}=\{\hat{m}_i,~i=1,\ldots,k\}$ such that
    \begin{align*}
        \hat{S} :&= \argmin_{S \subseteq \mathbb{R}^d : |S|=k} \sum_{i=1}^k \sum_{x \in \substack{S_i}} d(x,m_i) \\&= \argmin_{S \subseteq \mathbb{R}^d : |S|=k} \sum_{x \in \mathcal X} d(x,S).    
    \end{align*}
\end{definition}
\begin{theorem}
    Let $\mathcal X=\{x_i,~i=1,\ldots,n\}$ be a data set in $\mathbb{R}^d$ and  let $\rho := \frac{1}{n} \sum_{i=1}^n \delta_{\substack{x_i}}$ be the associated empirical measure. Moreover, let $\hat{S}=\{\hat{m}_i,~i=1,\ldots,k\}$ be the geometric k-medians for $\mathcal X$ and let $\hat{S}_i := \{ x \in \mathcal X : \hat{m}_i = \argmin_{m \in \hat{S}} \norm{m - x}_2 \}$, i.e.\ the points in $\mathcal{X}$ for which the closest point in $\hat{S}$ is $\hat{m}_i$. Then,
    \begin{gather*}
        \pi_{\substack{\hat{S}}} \rho=\argmin_{\substack{\mu :\supp(\mu) = k }} W_1(\rho, \mu),
    \end{gather*}
    where $\pi_{\substack{\hat{S}}} = \frac{1}{n}\sum_{i=1}^n \delta_{\substack{\pi_{\substack{\hat{S}}}}(x_i)} = \sum_{i=1}^k \frac{|\hat{S}_i|}{n} \delta_{\substack{\hat{m}_i}}$.
\end{theorem}

Since $\pi_{\substack{\hat{S}}}\rho$ is an empirical measure concentrated on $\hat{S}$, Theorem [REF:th:w1-kmedians] states that the empirical distribution concentrated on geometric $k$-medians is the minimiser of the Wasserstein-1 distance between the empirical distribution of the data $\mathcal X$ and all distributions $\mu$ with  $\supp(\mu)=k$.

\begin{proof}
    We can proceed in close analogy with [CITE:canas] where a connection between k-means and $W_2$ is examined.
    We have
    \begin{align*}
        \hat{S} &= \argmin_{S \subseteq \mathbb{R}^d : |S|=k} \sum_{x \in \mathcal X} d(x,S) 
        =  \argmin_{S \subseteq \mathbb{R}^d : |S|=k}\frac{1}{n} \sum_{x \in \mathcal X} d(x,S) \\
        &= \argmin_{S \subseteq \mathbb{R}^d : |S|=k} \mathbb{E}_{x\sim \rho} d(x, S) = \argmin_{S \subseteq \mathbb{R}^d \colon |S|=k} W_1(\rho, \pi_S \rho),
    \end{align*}
    where the last equality follows from Lemma [REF:thm:exp_wass].
    Hence,
    \begin{gather*}
        \pi_{\substack{\hat{S}}}\rho = \argmin_{\substack{\pi_S \rho\colon S\subseteq \mathbb{R}^d, 
        |S|=k}} W_1(\rho, \pi_S \rho).
    \end{gather*}
    This means that $\pi_{\substack{\hat{S}}}\rho$ minimises the Wasserstein distance from $\rho$ among all measures which are projections on a set $S$ supported on $k$ points. On the other hand, we know that a projection measure always minimises the Wasserstein over all measures with support contained in a set $S$ (Lemma [REF:thm: proj_min]). Together, this implies that $\pi_{\substack{\hat{S}}}\rho$ minimises Wasserstein distance among all measures with support contained in a set $S$ supported on $k$ points. 
\end{proof}

