\subsection{Kullback-Leibler divergence}
\begin{equation}
\phi_+(x)= \begin{cases}
x \log(x) - x + 1 \text{ if $x \geq 0$,}\\
\infty \text{ otherwise.}
\end{cases}
\end{equation}
\begin{equation}
\partial \phi_+(x)= \begin{cases}
\left\{ \log(x) \right\} \text{ if $x > 0$,}\\
\emptyset \text{ otherwise.}
\end{cases}
\end{equation}
\begin{equation}
\phi'(\infty)=\infty.
\end{equation}
\begin{equation}
\phi_+^*(x)=e^x-1.
\end{equation}
\begin{equation}
{\phi_+^*}'(x)=e^x.
\end{equation}
\begin{equation}
{\phi_+^*}''(x)=e^x.
\end{equation}

\subsection{Reverse Kullback-Leibler divergence}
\begin{equation}
\phi_+(x)= \begin{cases}
x-1-\log(x) \text{ if $x \geq 0$,}\\
\infty \text{ otherwise.}
\end{cases}
\end{equation}
\begin{equation}
\partial \phi_+(x)= \begin{cases}
\left\{ \frac{x-1}{x} \right\} \text{ if $x > 0$,}\\
\emptyset \text{ otherwise.}
\end{cases}
\end{equation}
\begin{equation}
\phi'(\infty)=1.
\end{equation}
\begin{equation}
\phi_+^*(x)=\begin{cases}
-\log(1-x) \text{ if $x \leq 1$,}\\
\infty \text{ otherwise.}
\end{cases}
\end{equation}
\begin{equation}
{\phi_+^*}'(x)=\frac{1}{1-x}.
\end{equation}
\begin{equation}
{\phi_+^*}''(x)=\frac{1}{(1-x)^2}.
\end{equation}

\subsection{$\chi^2$ divergence}
\begin{equation}
\phi_+(x)= \begin{cases}
(x-1)^2 \text{ if $x \geq 0$,}\\
\infty \text{ otherwise.}
\end{cases}
\end{equation}
\begin{equation}
\partial \phi_+(x)= \begin{cases}
\left\{ 2x-2 \right\} \text{ if $x \geq 0$,}\\
\emptyset \text{ otherwise.}
\end{cases}
\end{equation}
\begin{equation}
\phi'(\infty)=\infty.
\end{equation}
\begin{equation}
\phi_+^*(x)=
\begin{cases}
\frac{1}{4}x^2+x \text{ if $x \geq -2$},\\
-1 \text{ otherwise.}
\end{cases}
\end{equation}
