{\phi_+^*}'(x)=
\begin{cases}
\frac{1}{2}x+1 \text{ if $x \geq -2$},\\
0 \text{ otherwise.}
\end{cases}
\end{equation}
\begin{equation}
{\phi_+^*}''(x)=
\begin{cases}
\frac{1}{2} \text{ if $x \geq -2$},\\
0 \text{ otherwise.}
\end{cases}
\end{equation}

\subsection{Reverse $\chi^2$ divergence}
\begin{equation}
\phi_+(x)= \begin{cases}
\frac{1}{x}+x-2 \text{ if $x \geq 0$,}\\
\infty \text{ otherwise.}
\end{cases}
\end{equation}
\begin{equation}
\partial \phi_+(x)= \begin{cases}
\left\{ 1-\frac{1}{x^2} \right\} \text{ if $x > 0$,}\\
\emptyset \text{ otherwise.}
\end{cases}
\end{equation}
\begin{equation}
\phi'(\infty)=1.
\end{equation}
\begin{equation}
\phi_+^*(x)=\begin{cases}
2-2\sqrt{1-x} \text{ if $x \leq 1$,}\\
\infty \text{ otherwise.}
\end{cases}
\end{equation}
\begin{equation}
{\phi_+^*}'(x)=\frac{1}{\sqrt{1-x}}.
\end{equation}
\begin{equation}
{\phi_+^*}''(x)=\frac{1}{2\sqrt{1-x}^3}.
\end{equation}

\subsection{Squared Hellinger divergence}
\begin{equation}
\phi_+(x)= \begin{cases}
(\sqrt{x}-1)^2 \text{ if $x \geq 0$,}\\
\infty \text{ otherwise.}
\end{cases}
\end{equation}
\begin{equation}
\partial \phi_+(x)= \begin{cases}
\left\{ 1-\frac{1}{\sqrt{x}} \right\} \text{ if $x > 0$,}\\
\emptyset \text{ otherwise.}
\end{cases}
\end{equation}
\begin{equation}
\phi'(\infty)=1.
\end{equation}
\begin{equation}
\phi_+^*(x)=\begin{cases}
\frac{x}{1-x} \text{ if $x \leq 1$,}\\
\infty \text{ otherwise.}
\end{cases}
\end{equation}
\begin{equation}
{\phi_+^*}'(x)=\frac{1}{(1-x)^2}.
\end{equation}
\begin{equation}
{\phi_+^*}''(x)=\frac{2}{(1-x)^3}.
\end{equation}

\subsection{Jensen-Shannon divergence}
\begin{equation}
\phi_+(x)= \begin{cases}
x\log(x)-(x+1)\log(\frac{x+1}{2}) \text{ if $x \geq 0$,}\\
\infty \text{ otherwise.}
\end{cases}
\end{equation}
\begin{equation}
\partial \phi_+(x)= \begin{cases}
\left\{ \log(x)-\log(x+1)+\log(2) \right\} \text{ if $x > 0$,}\\
\emptyset \text{ otherwise.}
\end{cases}
\end{equation}
\begin{equation}
\phi'(\infty)=\log(2).
\end{equation}
\begin{equation}
\phi_+^*(x)=\begin{cases}
-\log(2-e^x) \text{ if $x \leq \log(2)$,}\\
\infty \text{ otherwise.}
\end{cases}
\end{equation}
\begin{equation}
{\phi_+^*}'(x)=\frac{1}{2e^{-x}-1}.
\end{equation}
\begin{equation}
{\phi_+^*}''(x)=\frac{2e^x}{(e^x-2)^2}.
\end{equation}

\subsection{Jeffreys divergence}
\begin{equation}
\phi_+(x)= \begin{cases}
(x-1)\log(x) \text{ if $x \geq 0$,}\\
\infty \text{ otherwise.}
\end{cases}
\end{equation}
\begin{equation}
\partial \phi_+(x)= \begin{cases}
\left\{ \log(x)-\frac{1}{x}+1 \right\} \text{ if $x > 0$,}\\
\emptyset \text{ otherwise.}
\end{cases}
\end{equation}
\begin{equation}
\phi'(\infty)=\infty.
\end{equation}
\begin{equation}
\phi_+^*(x)=x+W(e^{1-x})+\frac{1}{W(e^{1-x})}-2.
\end{equation}
\begin{equation}
{\phi_+^*}'(x)=\frac{1}{W(e^{1-x})}.
\end{equation}
\begin{equation}
{\phi_+^*}''(x)=\frac{1}{W(e^{1-x})}-\frac{1}{W(e^{1-x})+1}.
\end{equation}

Here $W$ denotes the principal branch of the Lambert W function, also called the product logarithm, defined implicitly by the relation $W(x)e^{W(x)}=x$. This can be computed by Newton's method and differentiated implicitly. For stability, since we only need the value of $W(e^{1-x})$, we compute $W(e^{1-x})$ explicitly instead of composing the Lambert W function with $e^{1-x}$.

\subsection{Triangular discrimination divergence}
\begin{equation}
\phi_+(x)= \begin{cases}
\frac{(x-1)^2}{x+1} \text{ if $x \geq 0$,}\\
\infty \text{ otherwise.}
\end{cases}
\end{equation}
\begin{equation}
\partial \phi_+(x)= \begin{cases}
\left\{ \frac{(x-1)(x+3)}{(x+1)^2} \right\} \text{ if $x \geq 0$,}\\
\emptyset \text{ otherwise.}
\end{cases}
\end{equation}
\begin{equation}
\phi'(\infty)=1.
\end{equation}
\begin{equation}
\phi_+^*(x)=\begin{cases}
-1 \text{ if $x < -3$,}\\
(\sqrt{1-x}-1)(\sqrt{1-x}-3) \text{ if $-3 \leq x \leq 1$,}\\
\infty \text{ otherwise.}
\end{cases}
\end{equation}
\begin{equation}
{\phi_+^*}'(x)=\begin{cases}
0 \text{ if $x < -3$,}\\
\frac{2}{\sqrt{1-x}}-1 \text{ if $-3 \leq x \leq 1$.}\\
\end{cases}
\end{equation}
\begin{equation}
{\phi_+^*}''(x)=\begin{cases}
0 \text{ if $x < -3$,}\\
\frac{1}{(\sqrt{1-x})^3} \text{ if $-3 \leq x \leq 1$.}\\
\end{cases}
\end{equation}

